package info.deltaindices.volumecamera;
import android.app.*;import android.content.*;import android.content.pm.PackageManager;import android.media.MediaRecorder;import android.net.Uri;import android.os.*;import android.provider.MediaStore;import androidx.camera.core.*;import androidx.camera.lifecycle.ProcessCameraProvider;import androidx.core.content.ContextCompat;import androidx.lifecycle.LifecycleService;import com.google.common.util.concurrent.ListenableFuture;import java.text.SimpleDateFormat;import java.util.*;import java.util.concurrent.*;

public final class CaptureService extends LifecycleService {
 static final String ACTION_START="info.deltaindices.volumecamera.capture.START",ACTION_STOP="info.deltaindices.volumecamera.capture.STOP",ACTION_COUNT="info.deltaindices.volumecamera.capture.COUNT";
 private final Handler handler=new Handler(Looper.getMainLooper());private final ExecutorService io=Executors.newSingleThreadExecutor();private ImageCapture capture;private ProcessCameraProvider provider;private MediaRecorder recorder;private ParcelFileDescriptor audioDescriptor;private Uri audioUri;private boolean audioStarted=false,stopping=false;private String sessionBase;private int photoIndex=0;
 private final Runnable cycle=new Runnable(){public void run(){take();}};
 @Override public void onCreate(){super.onCreate();sessionBase=Settings.nextSessionBase(this);startForeground(Notifications.CAPTURE_ID,Notifications.build(this,"Camera and microphone active","Rear camera, microphone and Drive queue · every "+Settings.interval(this)+" seconds",true));Settings.prefs(this).edit().putBoolean(Settings.CAPTURE_ACTIVE,true).putInt(Settings.SESSION_COUNT,0).remove(Settings.CAPTURE_ERROR).apply();broadcastCount();if(checkSelfPermission(android.Manifest.permission.CAMERA)!=PackageManager.PERMISSION_GRANTED||checkSelfPermission(android.Manifest.permission.RECORD_AUDIO)!=PackageManager.PERMISSION_GRANTED){fail("Camera and microphone permissions are required");return;}try{startAudio();bindCamera();}catch(Exception e){fail("Could not start camera and microphone: "+e.getClass().getSimpleName()+(e.getMessage()==null?"":" · "+e.getMessage()));}}
 @Override public int onStartCommand(Intent intent,int flags,int id){super.onStartCommand(intent,flags,id);if(intent!=null&&ACTION_STOP.equals(intent.getAction())){stopCapture();return START_NOT_STICKY;}return START_NOT_STICKY;}
 private void bindCamera(){ListenableFuture<ProcessCameraProvider> future=ProcessCameraProvider.getInstance(this);future.addListener(()->{try{provider=future.get();capture=new ImageCapture.Builder().setFlashMode(ImageCapture.FLASH_MODE_OFF).setCaptureMode(ImageCapture.CAPTURE_MODE_MINIMIZE_LATENCY).build();provider.unbindAll();provider.bindToLifecycle(this,CameraSelector.DEFAULT_BACK_CAMERA,capture);handler.post(cycle);}catch(Exception e){fail("Could not open rear camera: "+e.getClass().getSimpleName());}},ContextCompat.getMainExecutor(this));}
 private void startAudio()throws Exception{String name=sessionBase+".m4a";ContentValues values=new ContentValues();values.put(MediaStore.MediaColumns.DISPLAY_NAME,name);values.put(MediaStore.MediaColumns.MIME_TYPE,"audio/mp4");if(Build.VERSION.SDK_INT>=29){values.put(MediaStore.MediaColumns.RELATIVE_PATH,"Music/VolumeCamera/Audio");values.put(MediaStore.MediaColumns.IS_PENDING,1);}audioUri=getContentResolver().insert(MediaStore.Audio.Media.EXTERNAL_CONTENT_URI,values);if(audioUri==null)throw new IllegalStateException("audio destination unavailable");audioDescriptor=getContentResolver().openFileDescriptor(audioUri,"w");if(audioDescriptor==null)throw new IllegalStateException("audio descriptor unavailable");recorder=Build.VERSION.SDK_INT>=31?new MediaRecorder(this):new MediaRecorder();recorder.setAudioSource(MediaRecorder.AudioSource.MIC);recorder.setOutputFormat(MediaRecorder.OutputFormat.MPEG_4);recorder.setAudioEncoder(MediaRecorder.AudioEncoder.AAC);recorder.setAudioEncodingBitRate(128000);recorder.setAudioSamplingRate(44100);recorder.setOutputFile(audioDescriptor.getFileDescriptor());recorder.prepare();recorder.start();audioStarted=true;}
 private void take(){if(stopping||capture==null)return;String name=sessionBase+"_"+String.format(Locale.US,"%06d",++photoIndex)+".jpg";ContentValues values=new ContentValues();values.put(MediaStore.Images.Media.DISPLAY_NAME,name);values.put(MediaStore.Images.Media.MIME_TYPE,"image/jpeg");if(Build.VERSION.SDK_INT>=29)values.put(MediaStore.Images.Media.RELATIVE_PATH,"DCIM/VolumeCamera");ImageCapture.OutputFileOptions options=new ImageCapture.OutputFileOptions.Builder(getContentResolver(),MediaStore.Images.Media.EXTERNAL_CONTENT_URI,values).build();capture.takePicture(options,io,new ImageCapture.OnImageSavedCallback(){public void onImageSaved(ImageCapture.OutputFileResults out){Uri uri=out.getSavedUri();if(uri!=null){DriveSync.enqueue(CaptureService.this,uri,name);int count=Settings.prefs(CaptureService.this).getInt(Settings.SESSION_COUNT,0)+1;Settings.prefs(CaptureService.this).edit().putInt(Settings.SESSION_COUNT,count).apply();broadcastCount();}handler.postDelayed(cycle,Settings.interval(CaptureService.this)*1000L);}public void onError(ImageCaptureException e){handler.postDelayed(cycle,Settings.interval(CaptureService.this)*1000L);}});}
 private void broadcastCount(){Intent event=new Intent(ACTION_COUNT).setPackage(getPackageName()).putExtra("count",Settings.prefs(this).getInt(Settings.SESSION_COUNT,0)).putExtra("active",Settings.prefs(this).getBoolean(Settings.CAPTURE_ACTIVE,false));sendBroadcast(event);}
 private void fail(String message){ErrorLog.record(this,"capture-service",message);Settings.prefs(this).edit().putString(Settings.CAPTURE_ERROR,message).apply();stopCapture();}
 private void stopAudio(){if(recorder==null)return;boolean valid=audioStarted;try{if(audioStarted)recorder.stop();}catch(RuntimeException e){valid=false;}finally{try{recorder.release();}catch(Exception ignored){}recorder=null;audioStarted=false;try{if(audioDescriptor!=null)audioDescriptor.close();}catch(Exception ignored){}audioDescriptor=null;}if(audioUri!=null){if(valid){if(Build.VERSION.SDK_INT>=29){ContentValues ready=new ContentValues();ready.put(MediaStore.MediaColumns.IS_PENDING,0);getContentResolver().update(audioUri,ready,null,null);}DriveSync.enqueueAudio(this,audioUri,sessionBase+".m4a");}else getContentResolver().delete(audioUri,null,null);audioUri=null;}}
 private void stopCapture(){if(stopping)return;stopping=true;handler.removeCallbacksAndMessages(null);if(provider!=null)provider.unbindAll();stopAudio();Settings.prefs(this).edit().putBoolean(Settings.CAPTURE_ACTIVE,false).apply();broadcastCount();stopForeground(STOP_FOREGROUND_REMOVE);stopSelf();}
 @Override public void onDestroy(){handler.removeCallbacksAndMessages(null);if(provider!=null)provider.unbindAll();stopAudio();io.shutdown();Settings.prefs(this).edit().putBoolean(Settings.CAPTURE_ACTIVE,false).apply();broadcastCount();super.onDestroy();}
}
